3	import org.junit.jupiter.api.Tag;
4	import org.junit.jupiter.api.Test;
5	import static org.junit.jupiter.api.Assertions.assertTrue;
6	
7	/** welcome-notify: on successful create, a NOTIFY log line carries the owner id and the
8	 * memberId. */
9	@Tag("cp57")
10	class Cp57Tests extends AcceptanceBase {
11	
12		@Test
13		void coreEnqueuesWelcome() throws Exception {
14			try (AuditLogCapture notify = new AuditLogCapture("NOTIFY")) {
15				int id = createOwnerOk(structuredOwner());
16				String memberId = fetchOwner(id).get("memberId").asText();
17				assertTrue(notify.anyContains(String.valueOf(id), memberId));
18			}
19		}
20	}
