105	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
106	        Map.of("61", 9, "1", 10);
107	
108	    /**
109	     * Inclusive 4-digit postcode range {@code {low, high}} per region, the fixed ground truth for
110	     * validating an owner's postcode against the region derived from its city. A region not listed
111	     * here (e.g. the {@code "UNKNOWN"} locality of an unmapped city) imposes no range constraint, so
112	     * any 4-digit postcode is accepted.
113	     */
114	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
115	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
116	
117	    /**
118	     * City -> canonical region, the fixed ground truth for deriving the region a postcode is
119	     * validated against. A city not listed here derives the {@code "UNKNOWN"} region, which imposes
120	     * no postcode-range constraint.
121	     */
122	    private static final Map<String, String> CITY_REGION = Map.of(
123	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
