187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
190	        HttpHeaders headers = new HttpHeaders();
191	        String idempotencyKey = currentIdempotencyKey();
192	        if (idempotencyKey != null) {
193	            Integer existingId = idempotentCreates.get(idempotencyKey);
194	            if (existingId != null) {
195	                Owner existing = this.clinicService.findOwnerById(existingId);
196	                if (existing != null) {
197	                    // Repeat of a create already performed under this key: return the original
198	                    // owner with 200 instead of creating a duplicate.
199	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
200	                }
201	            }
202	        }
203	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
204	        LocalDate suppliedDate = owner.getRegistrationDate();
205	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
206	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
207	        }
208	        LocalDate effectiveDate = suppliedDate != null ? suppliedDate : LocalDate.now();
209	        LocalDate registrationDate = toBusinessDay(effectiveDate);
210	        owner.setRegistrationDate(registrationDate);
211	        long createdToday = this.clinicService.findAllOwners().stream()
212	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
213	            .count();
214	        if (createdToday >= 100) {
215	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
216	        }
217	        owner.setBulkSignupWarning(createdToday > 80);
218	        if (!applyAddress(owner)) {
219	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
220	        }
221	        String telephone = toE164(owner.getTelephone());
222	        if (telephone == null) {
223	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
224	        }
225	        owner.setTelephone(telephone);
226	        if (owner.getEmail() != null) {
227	            String email = normalizeEmail(owner.getEmail());
228	            if (!EMAIL_PATTERN.matcher(email).matches()) {
229	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
230	            }
231	            if (isDisposableEmailDomain(email)) {
232	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
233	            }
234	            owner.setEmail(email);
235	        }
236	        if (!isPostcodeValidForCity(owner.getPostcode(), regionForCity(owner.getCity()))) {
237	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
238	        }
239	        String cityKey = householdKey(owner.getCity());
240	        long cityCount = this.clinicService.findAllOwners().stream()
241	            .filter(existing -> existing.getCity() != null
242	                && cityKey.equals(householdKey(existing.getCity())))
243	            .count();
244	        if (cityCount >= 50) {
245	            return new ResponseEntity<>(HttpStatus.CONFLICT);
246	        }
247	        // Approaching-capacity warning: the city already holds 40-49 owners, just short of the
248	        // hard limit of 50. The 50+ rejection above still applies unchanged.
249	        owner.setCapacityWarning(cityCount >= 40 && cityCount < 50);
250	        // The household is keyed on (normalized last name, postcode): every owner derives the same
251	        // deterministic householdId from those two fields, so owners sharing them are the same
252	        // household. This computed id is what duplicate detection and the household size below key off.
253	        String householdId = householdId(owner);
254	        owner.setHouseholdId(householdId);
255	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
256	            .filter(existing -> !existing.getDeleted())
257	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
258	            .toList();
259	        owner.setHouseholdSize(householdMembers.size() + 1);
260	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
261	        // Duplicate detection is now the single identityKey (below): the separate household-duplicate
262	        // 409 block from the computed householdId no longer applies. Two owners sharing a last name and
263	        // postcode but with different telephones therefore have different identity keys and are admitted
264	        // as a soft match rather than rejected. The householdId and householdSize computed above still
265	        // drive household sizing and the level ceiling below.
266	        // Level ceiling: an owner admitted into an already-populated household without declaring
267	        // membership has its membership level capped at one above the household's current maximum, so
268	        // an undeclared newcomer can never outrank the household it joined. Declared members and
269	        // household founders are left uncapped. With no existing household member no cap applies.
270	        if (!householdMembers.isEmpty() && !sharesHousehold) {
271	            int maxHouseholdLevel = householdMembers.stream()
272	                .mapToInt(Owner::getMembershipLevel)
273	                .max()
274	                .orElse(0);
275	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
276	        }
277	        // Single consolidated duplicate check: the telephone, email and household duplicate rules are
278	        // all expressed through the one derived identityKey (telephone|email|householdId). A create is
279	        // rejected only when a new owner's WHOLE identityKey equals an existing owner's; because the
280	        // telephone is part of the key, two household members with different telephones are allowed.
281	        // This still catches a full identity repeat even when it declares sharesHousehold.
282	        String identityKey = owner.getIdentityKey();
283	        boolean identityInUse = this.clinicService.findAllOwners().stream()
284	            .filter(existing -> !existing.getDeleted())
285	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
286	        if (identityInUse) {
287	            return new ResponseEntity<>(HttpStatus.CONFLICT);
288	        }
289	        // Soft-duplicate detection. A declared household member (sharesHousehold) is never a suspected
290	        // duplicate. Any other owner whose identityKey differs from an existing owner's but that shares
291	        // that owner's Soundex(last name) and postcode is flagged as a possible duplicate of the
292	        // earliest such owner. A full identity match would already have been rejected as a 409 above,
293	        // so every existing owner reaching here necessarily has a different identityKey.
294	        if (sharesHousehold) {
295	            owner.setPossibleDuplicate(false);
296	        } else {
297	            String softDuplicateLastNameSoundex = Owner.soundex(owner.getLastName());
298	            String softDuplicatePostcode = owner.getPostcode();
299	            Owner possibleDuplicate = softDuplicatePostcode == null ? null
300	                : this.clinicService.findAllOwners().stream()
301	                    .filter(existing -> !existing.getDeleted())
302	                    .filter(existing -> softDuplicateLastNameSoundex.equals(Owner.soundex(existing.getLastName())))
303	                    .filter(existing -> softDuplicatePostcode.equals(existing.getPostcode()))
304	                    .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
305	                    .min(Comparator.comparing(Owner::getId))
306	                    .orElse(null);
307	            if (possibleDuplicate != null) {
308	                owner.setPossibleDuplicate(true);
309	                owner.setPossibleDuplicateOf(possibleDuplicate.getId());
310	            } else {
311	                owner.setPossibleDuplicate(false);
312	            }
313	        }
314	        owner.setMemberId(memberId(owner));
315	        String firstNameKey = householdKey(owner.getFirstName());
316	        String namesakeLastNameKey = householdKey(owner.getLastName());
317	        long namesakeCount = this.clinicService.findAllOwners().stream()
318	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
319	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
320	            .count();
321	        owner.setNamesakeCount((int) namesakeCount);
322	        this.clinicService.saveOwner(owner);
323	        if (idempotencyKey != null) {
324	            idempotentCreates.put(idempotencyKey, owner.getId());
325	        }
326	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
327	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
328	            owner.getMembershipLevel());
329	        OwnerCreatedEvent event = new OwnerCreatedEvent(OWNER_CREATED_SEQUENCE.incrementAndGet(),
330	            owner.getId(), primaryIdentifier(owner), owner.getMembershipLevel());
331	        AUDIT.info("{}", event.toJson());
332	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
333	        headers.setLocation(UriComponentsBuilder.newInstance()
334	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
335	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
336	    }
