338	    /**
339	     * Validates an owner's postcode against the region derived from its city. The postcode is
340	     * optional: a {@code null} value is always accepted. When present it must fall within the
341	     * inclusive range mapped to the region by {@link #REGION_POSTCODES}; a region with no known
342	     * range (e.g. the {@code "UNKNOWN"} locality of an unmapped city) accepts any 4-digit postcode.
343	     * The 4-digit syntax itself is enforced upstream by bean validation.
344	     *
345	     * @param postcode the owner's postcode (may be {@code null})
346	     * @param locality the region derived from the owner's city
347	     * @return {@code true} when the postcode is absent, the region has no range, or the postcode is
348	     *         within the region's range; {@code false} when it is out of range
349	     */
350	    /**
351	     * The canonical region for the given city via the fixed {@link #CITY_REGION} table, or
352	     * {@code "UNKNOWN"} when the city is {@code null} or not in the table.
353	     *
354	     * @param city the owner's city (may be {@code null})
355	     * @return the canonical region, or {@code "UNKNOWN"}
356	     */
357	    /**
358	     * The {@code Idempotency-Key} header of the current request, trimmed, or {@code null} when the
359	     * header is absent, blank, or no servlet request is bound to the current thread.
360	     *
361	     * @return the idempotency key, or {@code null}
362	     */
363	    private String currentIdempotencyKey() {
364	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
365	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
366	            String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
367	            if (key != null && !key.isBlank()) {
368	                return key.trim();
369	            }
370	        }
371	        return null;
372	    }
373	
374	    private String regionForCity(String city) {
375	        if (city == null) {
376	            return "UNKNOWN";
377	        }
378	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
379	    }
