381	    private boolean isPostcodeValidForCity(String postcode, String locality) {
382	        if (postcode == null) {
383	            return true;
384	        }
385	        int[] range = REGION_POSTCODES.get(locality);
386	        if (range == null) {
387	            return true;
388	        }
389	        int value = Integer.parseInt(postcode);
390	        return value >= range[0] && value <= range[1];
391	    }
