393	    /**
394	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
395	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
396	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
397	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}. For
398	     * recognised country codes the national number (the digits after the country code) must also be
399	     * exactly the length that country requires ({@code '+61'} needs 9 national digits, {@code '+1'}
400	     * needs 10); a wrong national-number length yields {@code null}.
401	     *
402	     * @param telephone the raw telephone value (may be {@code null})
403	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
404	     *         a valid E.164 number
405	     */
406	    private String toE164(String telephone) {
407	        if (telephone == null) {
408	            return null;
409	        }
410	        String trimmed = telephone.trim();
411	        boolean hasCountryCode = trimmed.startsWith("+");
412	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
413	        if (hasCountryCode) {
414	            cleaned = cleaned.substring(1);
415	        }
416	        if (!cleaned.matches("[0-9]+")) {
417	            return null;
418	        }
419	        String digits;
420	        if (hasCountryCode) {
421	            digits = cleaned;
422	        } else {
423	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
424	            digits = "61" + national;
425	        }
426	        if (digits.length() < 8 || digits.length() > 15) {
427	            return null;
428	        }
429	        if (!hasValidNationalNumberLength(digits)) {
430	            return null;
431	        }
432	        return "+" + digits;
433	    }
434	
435	    /**
436	     * Checks the national-number length of an E.164 digit string (country code plus national
437	     * number, without the leading {@code '+'}) against its country code. When the number's country
438	     * code is one of the {@link #NATIONAL_NUMBER_LENGTHS recognised codes}, the digits after the
439	     * country code must number exactly what that country requires; the longest matching country
440	     * code wins. Numbers whose country code is not recognised are accepted here (they are governed
441	     * only by the generic total-length rule).
442	     *
443	     * @param digits the E.164 digits without the leading {@code '+'} (e.g. {@code "61412345678"})
444	     * @return {@code true} if the national-number length is acceptable for the country code
445	     */
446	    private boolean hasValidNationalNumberLength(String digits) {
447	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
448	            .filter(entry -> digits.startsWith(entry.getKey()))
449	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
450	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
451	            .orElse(true);
452	    }
