454	    /**
455	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
456	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
457	     *
458	     * @param email the raw email value (must not be {@code null})
459	     * @return the trimmed, lower-cased email
460	     */
461	    private String normalizeEmail(String email) {
462	        return email.trim().toLowerCase(Locale.ROOT);
463	    }
