465	    /**
466	     * Whether the domain of the given normalized email is on the disposable-domain blocklist
467	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The domain is the substring after the last {@code '@'};
468	     * an email without an {@code '@'} carries no blocked domain.
469	     *
470	     * @param email the trimmed, lower-cased email
471	     * @return {@code true} when the email's domain is blocklisted
472	     */
473	    private boolean isDisposableEmailDomain(String email) {
474	        int at = email.lastIndexOf('@');
475	        if (at < 0) {
476	            return false;
477	        }
478	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
479	    }
