481	    /**
482	     * Applies the owner's address, preferring the structured form over the flat one. When a
483	     * non-blank {@code addressLine1} is supplied the structured fields are normalized in place and
484	     * the flat {@code address} is composed as the normalized {@code addressLine1} followed, when a
485	     * non-blank {@code addressLine2} is present, by a single space and the normalized
486	     * {@code addressLine2}. Otherwise the flat {@code address} is normalized in place. An owner
487	     * that supplies neither a non-blank {@code addressLine1} nor a non-blank flat {@code address}
488	     * is invalid.
489	     *
490	     * @param owner the owner whose address fields are normalized and composed in place
491	     * @return {@code true} when a usable address was applied, {@code false} when none was supplied
492	     */
493	    private boolean applyAddress(Owner owner) {
494	        String line1 = owner.getAddressLine1();
495	        if (line1 != null && !line1.isBlank()) {
496	            String normalizedLine1 = normalizeAddress(line1);
497	            owner.setAddressLine1(normalizedLine1);
498	            String composed = normalizedLine1;
499	            String line2 = owner.getAddressLine2();
500	            if (line2 != null && !line2.isBlank()) {
501	                String normalizedLine2 = normalizeAddress(line2);
502	                owner.setAddressLine2(normalizedLine2);
503	                composed = normalizedLine1 + " " + normalizedLine2;
504	            }
505	            owner.setAddress(composed);
506	            return true;
507	        }
508	        String address = normalizeAddress(owner.getAddress());
509	        if (address == null || address.isEmpty()) {
510	            return false;
511	        }
512	        owner.setAddress(address);
513	        return true;
514	    }
