516	    /**
517	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
518	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
519	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
520	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
521	     * normalized form, and every household comparison uses it.
522	     *
523	     * @param address the raw address value (may be {@code null})
524	     * @return the normalized address, or {@code null} if the input was {@code null}
525	     */
526	    private String normalizeAddress(String address) {
527	        if (address == null) {
528	            return null;
529	        }
530	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
531	        if (collapsed.isEmpty()) {
532	            return collapsed;
533	        }
534	        String[] tokens = collapsed.split(" ");
535	        StringBuilder sb = new StringBuilder(collapsed.length());
536	        for (int i = 0; i < tokens.length; i++) {
537	            if (i > 0) {
538	                sb.append(' ');
539	            }
540	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
541	        }
542	        return sb.toString();
543	    }
544	
545	    /**
546	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
547	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
548	     * so that owners are compared case-insensitively with collapsed whitespace.
549	     *
550	     * @param value the raw value (must not be {@code null})
551	     * @return the normalized comparison key
552	     */
553	    private String householdKey(String value) {
554	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
555	    }
556	
557	    /**
558	     * Derives a stable, shared household identifier for the owner's household: the first 12 hex
559	     * characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}, where the
560	     * last name is normalized with {@link #householdKey} and an absent postcode is rendered as the
561	     * empty string. Because it is a pure function of the last name and postcode, every owner sharing
562	     * those two fields derives the identical identifier and therefore belongs to the same household.
563	     *
564	     * @param owner the owner whose household identifier is derived
565	     * @return the stable household identifier
566	     */
567	    private String householdId(Owner owner) {
568	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
569	        String key = householdKey(owner.getLastName()) + "|" + postcode;
570	        try {
571	            byte[] digest = MessageDigest.getInstance("SHA-256")
572	                .digest(key.getBytes(StandardCharsets.UTF_8));
573	            StringBuilder sb = new StringBuilder(digest.length * 2);
574	            for (byte b : digest) {
575	                sb.append(String.format("%02x", b));
576	            }
577	            return sb.substring(0, 12);
578	        }
579	        catch (java.security.NoSuchAlgorithmException e) {
580	            throw new IllegalStateException("SHA-256 not available", e);
581	        }
582	    }
