584	    /**
585	     * The owner's current primary identifier, the value carried by the structured
586	     * {@code OWNER_CREATED} audit event: the owner's {@link Owner#getMemberId() memberId}, the
587	     * single unified identifier that replaced the former customer code.
588	     *
589	     * @param owner the freshly created owner (with its member id already assigned)
590	     * @return the owner's current primary identifier
591	     */
592	    private String primaryIdentifier(Owner owner) {
593	        return owner.getMemberId();
