596	    /**
597	     * Immutable structured audit event emitted alongside the human-readable audit line when an owner
598	     * is created. It is serialized to a compact JSON object and published to the {@code AUDIT}
599	     * logger so it can be routed and asserted independently of the diagnostic log. The
600	     * {@code memberId} field carries the owner's {@link #primaryIdentifier(Owner) current primary
601	     * identifier}, the unified member id.
602	     */
603	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
604	                                     Integer membershipLevel) {
605	
606	        private static final String EVENT = "OWNER_CREATED";
607	
608	        private String toJson() {
609	            return "{\"seq\":" + this.seq
610	                + ",\"ownerId\":" + this.ownerId
611	                + ",\"memberId\":" + quote(this.memberId)
612	                + ",\"membershipLevel\":" + this.membershipLevel
613	                + ",\"event\":\"" + EVENT + "\"}";
614	        }
615	
616	        private static String quote(String value) {
617	            if (value == null) {
618	                return "null";
619	            }
620	            String escaped = value.replace("\\", "\\\\").replace("\"", "\\\"");
621	            return "\"" + escaped + "\"";
622	        }
623	    }
