625	    /**
626	     * Builds the member id for a newly registered owner in the form
627	     * {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION} is the region code (the same region
628	     * derivation shared with {@link Owner#getLocality() locality}: postcode range first, falling
629	     * back to the city, or {@code 'UNKNOWN'}); {@code FY} is the 2-digit fiscal year of the
630	     * registration date (the last two digits of {@link Owner#getFiscalYear()}); {@code HASH8} is the
631	     * first 8 upper-case hex characters of the SHA-256 digest of the normalized telephone
632	     * concatenated with the last name (the same HASH8 used by the region-and-hash identity); and
633	     * {@code CHK} is a single Luhn check digit computed over the decimal digits of
634	     * {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW261A2B3C4D7'}). When the computed id collides with
635	     * an existing owner's member id, {@code '-<n>'} is appended using the smallest {@code n} of 2 or
636	     * more that makes the result unique, guaranteeing distinct owners always receive distinct member
637	     * ids.
638	     *
639	     * @param owner the owner whose member id is derived (with normalized telephone and registration
640	     *              date already set)
641	     * @return the assigned member id
642	     */
643	    private String memberId(Owner owner) {
644	        String region = owner.getLocality();
645	        String fiscalYear = owner.getFiscalYear();
646	        String fy = fiscalYear == null ? "00" : fiscalYear.substring(fiscalYear.length() - 2);
647	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName(), 8);
648	        String core = region + fy + hash8;
649	        String base = core + luhnCheckDigit(core);
650	        Set<String> existingIds = this.clinicService.findAllOwners().stream()
651	            .map(Owner::getMemberId)
652	            .filter(id -> id != null)
653	            .collect(Collectors.toSet());
654	        if (!existingIds.contains(base)) {
655	            return base;
656	        }
657	        int n = 2;
658	        while (existingIds.contains(base + "-" + n)) {
659	            n++;
660	        }
661	        return base + "-" + n;
662	    }
663	
664	    /**
665	     * The single Luhn check digit ({@code 0}-{@code 9}) computed with the standard Luhn algorithm
666	     * over the decimal digits contained in {@code value} (non-digit characters are ignored).
667	     *
668	     * @param value the string whose decimal digits are checked
669	     * @return the Luhn check digit
670	     */
671	    private static int luhnCheckDigit(String value) {
672	        int sum = 0;
673	        boolean dbl = true;
674	        for (int i = value.length() - 1; i >= 0; i--) {
675	            char c = value.charAt(i);
676	            if (c < '0' || c > '9') {
677	                continue;
678	            }
679	            int d = c - '0';
680	            if (dbl) {
681	                d *= 2;
682	                if (d > 9) {
683	                    d -= 9;
684	                }
685	            }
686	            sum += d;
687	            dbl = !dbl;
688	        }
689	        return (10 - (sum % 10)) % 10;
690	    }
691	
692	    /**
693	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
694	     * UTF-8 bytes of {@code input}.
695	     *
696	     * @param input  the value to hash
697	     * @param length the number of leading hex characters to keep
698	     * @return the truncated, upper-cased hex digest
699	     */
700	    private String sha256UpperHex(String input, int length) {
701	        try {
702	            byte[] digest = MessageDigest.getInstance("SHA-256")
703	                .digest(input.getBytes(StandardCharsets.UTF_8));
704	            StringBuilder sb = new StringBuilder(digest.length * 2);
705	            for (byte b : digest) {
706	                sb.append(String.format("%02x", b));
707	            }
708	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
709	        }
710	        catch (java.security.NoSuchAlgorithmException e) {
711	            throw new IllegalStateException("SHA-256 not available", e);
712	        }
713	    }
714	
715	    /** Fixed public holidays that the business-day roll skips. */
716	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
717	        LocalDate.parse("2026-01-01"),
718	        LocalDate.parse("2026-01-26"),
719	        LocalDate.parse("2026-04-25"),
720	        LocalDate.parse("2026-12-25"),
721	        LocalDate.parse("2026-12-28"));
722	
723	    /**
724	     * Rolls a registration date forward onto a business day. When the given date falls on a
725	     * Saturday, Sunday or a listed public holiday it is advanced one day at a time until it
726	     * lands on a non-holiday weekday; a business day is returned unchanged.
727	     *
728	     * @param date the effective registration date (must not be {@code null})
729	     * @return the same date if it is already a business day, otherwise the next business day
730	     */
731	    private LocalDate toBusinessDay(LocalDate date) {
732	        while (isNonBusinessDay(date)) {
733	            date = date.plusDays(1);
734	        }
735	        return date;
736	    }
737	
738	    private boolean isNonBusinessDay(LocalDate date) {
739	        DayOfWeek dayOfWeek = date.getDayOfWeek();
740	        return dayOfWeek == DayOfWeek.SATURDAY
741	            || dayOfWeek == DayOfWeek.SUNDAY
742	            || PUBLIC_HOLIDAYS.contains(date);
743	    }
744	
745	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
746	    @Override
747	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
748	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
749	        if (currentOwner == null) {
750	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
751	        }
752	        String email = ownerFieldsDto.getEmail();
753	        if (email != null) {
754	            email = normalizeEmail(email);
755	            if (!EMAIL_PATTERN.matcher(email).matches()) {
756	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
757	            }
758	        }
759	        String telephone = toE164(ownerFieldsDto.getTelephone());
760	        if (telephone == null) {
761	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
762	        }
763	        currentOwner.setAddress(ownerFieldsDto.getAddress());
764	        currentOwner.setCity(ownerFieldsDto.getCity());
765	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
766	        currentOwner.setLastName(ownerFieldsDto.getLastName());
767	        currentOwner.setTelephone(telephone);
768	        currentOwner.setEmail(email);
769	        this.clinicService.saveOwner(currentOwner);
770	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
771	    }
772	
773	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
774	    @Transactional
775	    @Override
776	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
777	        Owner owner = this.clinicService.findOwnerById(ownerId);
778	        if (owner == null) {
779	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
780	        }
781	        // Soft-delete: flag the owner deleted and retain the record so it can still be read back.
782	        owner.setDeleted(true);
783	        this.clinicService.saveOwner(owner);
784	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
785	    }
786	
787	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
788	    @Override
789	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
790	        Owner owner = this.clinicService.findOwnerById(ownerId);
791	        if (owner == null) {
792	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
793	        }
794	        HttpHeaders headers = new HttpHeaders();
795	        Pet pet = petMapper.toPet(petFieldsDto);
796	        owner.setId(ownerId);
797	        pet.setOwner(owner);
798	        pet.getType().setName(null);
799	        this.clinicService.savePet(pet);
800	        PetDto petDto = petMapper.toPetDto(pet);
801	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
802	            .buildAndExpand(pet.getId()).toUri());
803	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
804	    }
805	
806	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
807	    @Override
808	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
809	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
810	        if (currentOwner != null) {
811	            Pet currentPet = this.clinicService.findPetById(petId);
812	            if (currentPet != null) {
813	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
814	                currentPet.setName(petFieldsDto.getName());
815	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
816	                this.clinicService.savePet(currentPet);
817	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
818	            }
819	        }
820	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
821	    }
822	
