824	    @Override
825	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
826	        HttpHeaders headers = new HttpHeaders();
827	        Visit visit = visitMapper.toVisit(visitFieldsDto);
828	        Pet pet = new Pet();
829	        pet.setId(petId);
830	        visit.setPet(pet);
831	        this.clinicService.saveVisit(visit);
832	        VisitDto visitDto = visitMapper.toVisitDto(visit);
833	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
834	            .buildAndExpand(visit.getId()).toUri());
835	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
